import React from 'react';
import { useInView } from 'react-intersection-observer';
import { 
  SiMysql, 
  SiPython, 
  SiMicrosoftexcel,
  SiTableau,
  SiPandas,
  SiNumpy,
  SiMicrosoft // 👈 add this
} from 'react-icons/si';

const Skills = () => {
  const [ref, inView] = useInView({
    triggerOnce: true,
    threshold: 0.1,
  });
  
  const skills = [
    { name: 'SQL', icon: SiMysql, level: 90, color: 'from-blue-500 to-blue-600' },
    { name: 'Python', icon: SiPython, level: 85, color: 'from-yellow-500 to-yellow-600' },
    
    // ❌ SiPowerbi removed
    // ✅ replaced with Microsoft icon
    { name: 'Power BI', icon: SiMicrosoft, level: 88, color: 'from-yellow-400 to-yellow-500' },
    
    { name: 'Excel', icon: SiMicrosoftexcel, level: 85, color: 'from-green-500 to-green-600' },
    { name: 'Pandas', icon: SiPandas, level: 80, color: 'from-blue-400 to-blue-500' },
    { name: 'NumPy', icon: SiNumpy, level: 80, color: 'from-teal-400 to-teal-500' },
  ];
  
  return (
    <section id="skills" className="py-20 bg-black">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-bold bg-gradient-to-r from-purple-500 to-pink-500 bg-clip-text text-transparent">
            Technical Skills
          </h2>
          <div className="w-24 h-1 bg-gradient-to-r from-purple-500 to-pink-500 mx-auto mt-4"></div>
          <p className="text-gray-400 mt-4">Technologies and tools I work with</p>
        </div>
        
        <div ref={ref} className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
          {skills.map((skill, idx) => (
            <div
              key={skill.name}
              className={`bg-gradient-to-br from-gray-900 to-gray-800 rounded-xl p-6 transform transition-all duration-500 hover:scale-105 hover:shadow-xl hover:shadow-purple-500/20 ${
                inView ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'
              }`}
              style={{ transitionDelay: `${idx * 100}ms` }}
            >
              <div className="flex items-center gap-4 mb-4">
                <skill.icon className="text-4xl text-purple-500" />
                <h3 className="text-xl font-semibold text-white">{skill.name}</h3>
              </div>
              
              <div className="relative pt-1">
                <div className="flex mb-2 items-center justify-between">
                  <span className="text-xs font-semibold text-purple-500">
                    Proficiency
                  </span>
                  <span className="text-xs font-semibold text-purple-500">
                    {skill.level}%
                  </span>
                </div>
                
                <div className="overflow-hidden h-2 mb-4 rounded bg-gray-700">
                  <div
                    style={{ width: `${skill.level}%` }}
                    className={`h-2 bg-gradient-to-r ${skill.color} transition-all duration-1000`}
                  ></div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Skills;
